// Custom airport icon - Simplificado con solo 3 colores
const createAirportIcon = (isSede = false, saturation = 0) => {
  let size, color, borderColor, borderWidth, shadow;

  if (isSede) {
    size = 32;
    color = '#dc3545';
    borderColor = '#FFD700';
    borderWidth = 4;
    shadow = '0 4px 16px rgba(220, 53, 69, 0.6)';
  } else {
    size = 22;
    borderColor = '#ffffff';
    borderWidth = 3;
    shadow = '0 3px 10px rgba(0,0,0,0.4)';

    if (saturation >= 80) {
      color = '#dc3545';
    } else if (saturation >= 50) {
      color = '#ffc107';
    } else {
      color = '#28a745';
    }
  }

  return new L.DivIcon({
    className: 'airport-marker',
    html: `
      <div style="
        background: ${color};
        border: ${borderWidth}px solid ${borderColor};
        border-radius: 50%;
        width: ${size}px;
        height: ${size}px;
        display: flex;
        align-items: center;
        justify-content: center;
        box-shadow: ${shadow};
        position: relative;
        cursor: pointer;
        transition: all 0.3s ease;
      ">
        <i class="fas fa-${isSede ? 'building' : 'plane'}" style="
          color: white;
          font-size: ${size * 0.4}px;
          ${isSede ? '' : 'transform: rotate(45deg);'}
          text-shadow: 0 1px 3px rgba(0,0,0,0.5);
          font-weight: bold;
        "></i>
        ${isSede ? `
          <div style="
            position: absolute; 
            top: -6px; 
            right: -6px; 
            background: #FFD700;
            border: 2px solid white; 
            border-radius: 50%; 
            width: 12px; 
            height: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 2px 6px rgba(0,0,0,0.3);
          ">
            <i class="fas fa-star" style="color: white; font-size: 6px;"></i>
          </div>
        ` : ''}
        ${!isSede && saturation >= 80 ? `
          <div style="
            position: absolute;
            top: -4px;
            right: -4px;
            background: #FF0000;
            border: 1px solid white;
            border-radius: 50%;
            width: 8px;
            height: 8px;
            animation: alertBlink 1s infinite;
          "></div>
        ` : ''}
      </div>
    `,
    iconSize: [size, size],
    iconAnchor: [size/2, size/2],
    popupAnchor: [0, -size/2]
  });
};

// Component to update markers dynamically
