        // Re-create marker only if it doesn't exist or needs an update
        if (!airportMarkers.current.has(airport.code) || airportMarkers.current.get(airport.code).options.icon.options.html !== icon.options.html) {
          if (airportMarkers.current.has(airport.code)) {
            map.removeLayer(airportMarkers.current.get(airport.code));
