                <div style="margin-top: 15px; padding: 10px; background: linear-gradient(135deg, #f8f9fa, #e9ecef); border-radius: 8px; text-align: center;">
                  <div style="color: #495057; font-size: 11px; font-weight: 600; margin-bottom: 4px;">ESTADO ACTUAL</div>
