                </div>
              </div>
            `);
          marker.addTo(map);
          flightMarkers.current.set(flight.id, marker);
        } else {
          // Just update position and icon if it's already there
          const marker = flightMarkers.current.get(flight.id);
          marker.setLatLng([flight.currentLat, flight.currentLng]);
          marker.setIcon(icon);
        }
      });
    }

    return () => {
      // Cleanup is handled by the maps above
    };
  }, [flights, airports, activeView, map]);

  return null;
}

